0 213.5C819.7 214.3 816.0 215.0 813.8 215.0C809.0 215.0 790.5 222.1 783.5 226.6C780.8 228.3 775.9 232.6 772.7 236.1C769.5 239.6 766.0 243.4 764.9 244.5C763.9 245.7 763.0 247.2 763.0 247.9C763.0 248.6 762.1 250.3 761.0 251.7C758.3 255.1 756.7 261.6 757.5 265.6C758.4 270.8 762.7 273.0 768.6 271.4Z", "x": 697.3, "y": 164.0, "w": 211.7, "h": 107.9, "ox": 8.4, "oy": 100.0}, {"d": "M837.3 282.6C838.1 281.8 839.3 279.8 840.0 278.1C840.7 276.4 841.6 275.0 842.1 275.0C842.6 275.0 843.8 274.2 844.8 273.2C848.6 269.4 854.2 267.0 860.4 266.5C863.9 266.2 868.9 265.5 871.6 264.9C874.3 264.3 883.0 263.6 891.0 263.4C915.5 262.6 919.7 259.6 915.6 246.0L914.3 241.5L907.4 241.6C900.3 241.7 892.5 243.3 890.3 245.1C889.7 245.7 886.3 246.1 882.8 246.1C870.3 246.0 845.9 250.1 842.8 252.7C841.8 253.6 840.4 254.0 839.5 253.6C838.6 253.3 837.7 253.6 837.4 254.3C837.2 255.0 834.5 257.4 831.6 259.5C823.7 265.2 820.9 273.1 824.5 280.0C825.7 282.2 826.8 283.0 829.7 283.3C831.8 283.5 834.0 283.7 834.7 283.8C835.3 283.9 836.5 283.4 837.3 282.6Z", "x": 763.0, "y": 193.5, "w": 214.0, "h": 90.3, "ox": 12.6, "oy": 100.0}, {"d": "M1015.1 296.6C1017.6 295.5 1018.4 287.3 1016.5 281.9C1013.0 272.2 1006.2 268.9 999.9 274.0C997.3 276.0 995.0 277.0 992.7 277.0C990.8 277.0 988.0 277.4 986.4 277.9C984.8 278.5 979.2 279.1 974.1 279.4C963.7 280.0 961.0 281.2 957.7 286.8C955.5 290.5 956.4 294.9 959.6 296.5C962.0 297.7 1012.7 297.8 1015.1 296.6Z", "x": 896.5, "y": 223.6, "w": 181.1, "h": 73.8, "ox": 54.2, "oy": 100.0}];

  // A small "random" wobble that is the same every time
  function wobble(seed) {
    const x = Math.sin(seed * 12.9898) * 43758.5453;
    return x - Math.floor(x) - 0.5;
  }

  // Tally marks in your style: loose uneven uprights, an overshooting slash.
  // Bundles of five: four uprights and one across.
  let groups = $derived.by(() => {
    const out = [];
    for (let g = 0; g * 5 < tabs; g++) {
      const count = Math.min(5, tabs - g * 5);
      const lines = [];
      for (let i = 0; i < Math.min(count, 4); i++) {
        const s = g * 10 + i;
        const x = 9 + i * 9 + wobble(s + 1) * 2;
        const top = 8 + wobble(s + 2) * 8;
        const bottom = 46 + wobble(s + 3) * 3;
        const tilt = wobble(s + 4) * 2.5;
        lines.push(`M${(x + tilt).toFixed(1)} ${top.toFixed(1)} L${(x - tilt / 2).toFixed(1)} ${bottom.toFixed(1)}`);
      }
      if (count === 5) {
        const s = g * 10 + 7;
        lines.push(`M2 ${(36 + wobble(s) * 3).toFixed(1)} L50 ${(18 + wobble(s + 1) * 3).toFixed(1)}`);
      }
      out.push(lines);
    }
    return out;
  });

  async function check() {
    try {
      const [t, seen] = await Promise.all([
        fetch(`${DB_URL}/status/tabs.json`).then((r) => r.json()),
        fetch(`${DB_URL}/status/lastSeen.json`).then((r) => r.json())
      ]);
      online = !!seen && Date.now() - seen < AWAY_AFTER_MS;
      if (online) tabs = t ?? 0; // keep the last count while away, so the tally sinks from the right number
    } catch {
      online = false;
    }
    loaded = true;
  }

  onMount(() => {
    check().then(() => setTimeout(() => (animate = true), 100));
    const timer = setInterval(check, 30000); // re-check every 30 seconds
    return () => clearInterval(timer);
  });
</script>

{#if loaded}
  <footer class="tab-status" class:away={!online} class:animate>
    <div class="art" aria-hidden="true">
      <div class="tally">
        {#each groups as lines, g}
          <svg viewBox="0 0 54 50" width="45" height="42">
            {#each lines as d, i}
              <path pathLength="1" {d} style="--i:{g * 5 + i}" />
            {/each}
          </svg>
        {/each}
      </div>

      <svg class="grass" viewBox="0 0 1024 304" width="95" height="28">
        <defs>
          {#each strands as s, k}
            <clipPath id="ts-grass-{k}" clipPathUnits="userSpaceOnUse">
              <rect x={s.x} y={s.y} width={s.w} height={s.h}
                style="--k:{k}; --r:{strands.length - 1 - k}; --h:{s.h + 8}px" />
            </clipPath>
          {/each}
        </defs>
        {#each strands as s, k}
          <g clip-path="url(#ts-grass-{k})">
            <path d={s.d} style="--k:{k}; transform-origin:{s.ox}% {s.oy}%" />
          </g>
        {/each}
      </svg>
    </div>

    <p class="lines">
      <span class="line on">
        Shivani is <span class="word"><span class="dot" aria-hidden="true"></span>online</span>
        and in the company of {tabs} {tabs === 1 ? 'tab' : 'tabs'} right now
      </span>
      <span class="line off">
        Shivani is <span class="word"><span class="dot" aria-hidden="true"></span>away</span>
        from the screen right now
      </span>
    </p>
  </footer>
{/if}

<style>
  /* No background of its own, so it sits on whatever the page colour is */
  .tab-status {
    padding: 64px 0 32px;
    font-family: var(--mono);
    font-size: var(--type-footer);
    color: var(--text);
  }

  /* ---------- drawing area ---------- */
  .art {
    position: relative;
    min-height: 42px;
    display: flex;
    align-items: flex-end;
  }

  .tally {
    display: flex;
    flex-wrap: wrap;
    gap: 7.5px 10.5px;
  }

  .tally svg,
  .grass {
    overflow: visible;
  }

  .tally path {
    fill: none;
    stroke: var(--status-green);
    stroke-width: 3.11;
    stroke-linecap: round;
    stroke-dasharray: 1 2;
    stroke-dashoffset: 0;
  }

  .grass {
    position: absolute;
    left: 0;
    bottom: 0;
  }

  .grass path {
    fill: var(--status-green);
    fill-rule: evenodd;
    transform-box: fill-box;
  }

  /* each strand hides below its own base until you're away */
  .grass rect {
    transform: translateY(var(--h));
  }

  /* ---------- away state ---------- */
  .away .tally path {
    stroke-dashoffset: -1.2; /* tally sinks out of view */
  }

  .away .grass rect {
    transform: translateY(0); /* strands rise */
  }

  .away .grass path {
    animation: ts-sway 2.6s ease-in-out infinite;
    animation-delay: calc(2.2s + var(--k) * 0.15s);
  }

  @keyframes ts-sway {
    0%, 100% { transform: rotate(0); }
    25% { transform: rotate(-2.5deg); }
    75% { transform: rotate(2.5deg); }
  }

  /* ---------- transitions (only after first load) ---------- */
  /* going away: tally sinks, then strands rise one by one, left to right */
  .animate.away .tally path {
    transition: stroke-dashoffset 0.6s ease-in-out;
    transition-delay: calc(var(--i) * 0.03s);
  }
  .animate.away .grass rect {
    transition: transform 0.55s ease-out;
    transition-delay: calc(0.7s + var(--k) * 0.09s);
  }

  /* coming back: strands sink one by one, right to left, then tally redraws */
  .animate:not(.away) .grass rect {
    transition: transform 0.4s ease-in;
    transition-delay: calc(var(--r) * 0.05s);
  }
  .animate:not(.away) .tally path {
    transition: stroke-dashoffset 0.6s ease-in-out;
    transition-delay: calc(1.1s + var(--i) * 0.03s);
  }

  /* ---------- the line of text ---------- */
  .lines {
    display: grid;
    margin: 8px 0 0;
  }

  .line {
    grid-area: 1 / 1; /* both lines sit in the same spot */
  }

  .line.off { opacity: 0; }
  .away .line.on { opacity: 0; }
  .away .line.off { opacity: 1; }

  .animate .line {
    transition: opacity 0.3s ease;
  }
  .animate.away .line.off { transition-delay: 0.35s; }
  .animate:not(.away) .line.on { transition-delay: 1s; }

  /* Rectangular state label with a dot, matching the status reference */
  .word {
    display: inline-flex;
    align-items: center;
    gap: 0.4em;
    padding: 0.1em 0.45em;
    background: var(--status-online-bg);
    font-weight: 500;
    white-space: nowrap;
  }

  .dot {
    flex: none;
    width: 0.55em;
    height: 0.55em;
    border-radius: 50%;
    background: var(--status-green);
  }

  .line.off .word {
    background: var(--sun);
  }

  .line.off .dot {
    background: var(--text);
  }

  /* people who have asked their device for less motion get no animation */
  @media (prefers-reduced-motion: reduce) {
    .tab-status *,
    .tab-status *::before {
      transition: none !important;
      animation: none !important;
    }
  }
</style>
